pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t) public {
        t = bound(t, 1, type(uint64).max);
        vm.warp(t);

        // first fallback call at time t succeeds
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // second fallback call at the SAME timestamp t
        vm.deal(address(this), 10 ether);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: after a successful call at time t, pastBlockTime == t,
        // so a repeat call at time t must revert.
        assertTrue(!ok2, "repeat call at same timestamp must revert");
    }
}

