pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, uint256 ts, address actor) public {
        // keep block number in a wide but valid domain
        blockNumber = bound(blockNumber, 0, 1_000_000_000);
        // timestamp must be strictly greater than pastBlockTime (which starts at 0,
        // or was the previous call's timestamp); keep it wide
        ts = bound(ts, 1, 2 ** 63);
        // actor must be a plain EOA distinct from the contract so transfer/withdraw works
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        vm.roll(blockNumber);
        vm.warp(ts);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok, "valid fallback call should succeed");

        // General rule: after a valid 10-ether fallback call with strictly increasing
        // timestamp, the contract's balance is drained to 0 exactly when the current
        // block number is a multiple of 15, and stays at 20 ether otherwise.
        if (blockNumber % 15 == 0) {
            assertEq(address(c).balance, 0, "must drain on multiples of 15");
        } else {
            assertEq(address(c).balance, 20 ether, "must keep funds off multiples of 15");
        }
    }
}

