// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 blk) public {
        // pick any positive timestamp and any block number divisible by 15 (payout block)
        uint256 b = bound(blk, 1, type(uint256).max / 15);
        vm.roll(b * 15);
        uint256 t = bound(ts, 1, type(uint64).max);
        vm.warp(t);

        // cooperative payee that reverts only if c's payout happens BEFORE pastBlockTime is recorded
        Detective d = new Detective(c);
        vm.deal(address(d), 10 ether);

        d.attack();

        // general rule: in a divisible block, a funded call with a payee that accepts
        // once pastBlockTime is recorded leaves the contract drained.
        assertTrue(address(c).balance == 0, "payout should have drained the contract");
    }
}

contract Detective {
    C public immutable c;

    constructor(C _c) { c = _c; }

    function attack() external {
        address(c).call{value: 10 ether}("");
    }

    receive() external payable {
        // accept the payout only if the contract has already recorded this block's timestamp
        if (c.pastBlockTime() != block.timestamp) revert();
    }
}
